import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';

// Adapter-owned parity check. The engine exports generated bytes to a caller-
// supplied directory without depending on the adapter's checked-in fixtures.
const output = await mkdtemp(join(tmpdir(), 'color-proof-'));
try {
    execFileSync('vp', ['run', '@atlowchemi/webfont-engine#test:color-proof'], {
        cwd: resolve(import.meta.dirname, '../../..'),
        env: { ...process.env, COLOR_PROOF_OUTPUT_DIR: output },
        stdio: 'inherit',
        shell: process.platform === 'win32',
    });
    await Promise.all(
        ['color-rvrn.ttf', 'color-rvrn.woff', 'color-rvrn.woff2'].map(async name => {
            const actual = await readFile(join(output, name));
            const fixture = resolve(import.meta.dirname, '../tests/browser/fixtures', name);
            if (process.env.UPDATE_COLOR_PROOF_FIXTURE === '1') await writeFile(fixture, actual);
            assert.deepEqual(actual, await readFile(fixture), `${name}: inspect changes before accepting with UPDATE_COLOR_PROOF_FIXTURE=1`);
        }),
    );
    console.log('Color browser fixtures match engine-generated TTF, WOFF, and WOFF2.');
} finally {
    await rm(output, { recursive: true, force: true });
}
